{
  "items": [
    {
      "path": "tools.linear.list_comments",
      "description": "List comments on a Linear issue, project, initiative, document, project milestone, or project/initiative status update. Provide exactly one of `issueId`, `projectId`, `initiativeId`, `documentId`, `milestoneId`, or `statusUpdateId`. `statusUpdateType` applies only to `statusUpdateId`; omit it for every other parent. For issues, projects, and initiatives this returns both top-level discussion threads and inline description comments. Inline (anchored) comments carry a non-null `quotedText` set to the snippet of description text they reference. Returned comments include `author` and nullable `onBehalfOf`; when set, `onBehalfOf` identifies the user the agent author acted for. Files uploaded in comment bodies are returned in `attachments` with titles and download URLs, not issue attachment IDs. Signed upload URLs expire after five minutes; call list_comments again to refresh them. Download documents using these URLs and process them with your own file tools.",
      "signature": "tools.linear.list_comments({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /**
   * Issue ID or identifier (e.g., LIN-123). P-prefixed identifiers (e.g., P-ENG-123) are projects, not issues (provide exactly one parent)
   */
  issueId?: string,
  /** Project name, ID, identifier (e.g., P-ENG-123), or slug (provide exactly one parent) */
  projectId?: string,
  /** Initiative name, ID, identifier (e.g., I-123), or slug (provide exactly one parent) */
  initiativeId?: string,
  /** Document ID or slug (provide exactly one parent) */
  documentId?: string,
  /** Milestone UUID (provide exactly one parent). Resolve milestone names via `list_milestones` first. */
  milestoneId?: string,
  /** Status update UUID (provide exactly one parent). Resolve status updates via `get_status_updates` first. */
  statusUpdateId?: string,
  /**
   * Set only together with `statusUpdateId`; omit for issue, project, initiative, document, and milestone comments. Type of status update named by `statusUpdateId`, as returned by `get_status_updates`. Omit to check both project and initiative status updates.
   */
  statusUpdateType?: "project" | "initiative",
}): Promise<unknown>"
    },
    {
      "path": "tools.linear.list_issue_labels",
      "description": "List available issue labels in a Linear workspace or team. A retired label carries `retiredAt` and cannot be applied to new issues.",
      "signature": "tools.linear.list_issue_labels({
  /** Maximum number of results to return per page. @default 50 @maximum 250 */
  limit?: number,
  /** Omit for the first page. To continue, pass the previous response's cursor when hasNextPage is true */
  cursor?: string,
  /** Timestamp to sort results by: creation time or last update time. @default "updatedAt" */
  orderBy?: "createdAt" | "updatedAt",
  /** Filter by name */
  name?: string,
  /** Team name or ID */
  team?: string,
  /** Include archived items. @default false */
  includeArchived?: boolean,
  /**
   * Include label groups in the results, marked with `isGroup`. A group cannot be applied directly; retiring or restoring one cascades to its child labels
   * @default false
   */
  includeGroups?: boolean,
}): Promise<unknown>"
    }
  ],
  "remaining": 98,
  "next": {
    "offset": 2
  }
}

